1. Create frontend/src/components/VoiceExplainer.jsx:
```jsx
import React, { useState, useRef } from 'react';
import { api } from '../services/api';

const LANGUAGES = [
  { code: 'en', label: 'EN', locale: 'en-IN' },
  { code: 'ta', label: 'தமிழ்', locale: 'ta-IN' },
  { code: 'hi', label: 'हिंदी', locale: 'hi-IN' },
];

function VoiceExplainer({ text, label = 'Listen' }) {
  const [lang, setLang] = useState('en');
  const [displayText, setDisplayText] = useState(text);
  const [translating, setTranslating] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const utterRef = useRef(null);

  const handleLangChange = async (newLang) => {
    setLang(newLang);
    if (newLang === 'en') {
      setDisplayText(text);
      return;
    }
    setTranslating(true);
    try {
      const res = await api.post('/ai/explain/', { text, language: newLang });
      setDisplayText(res.data.explanation || text);
    } catch(err) {
      console.error('Translation failed', err);
      setDisplayText(text);
    } finally {
      setTranslating(false);
    }
  };

  const handleListen = () => {
    if (!window.speechSynthesis) return;
    if (speaking) {
      window.speechSynthesis.cancel();
      setSpeaking(false);
      return;
    }
    const utt = new SpeechSynthesisUtterance(displayText);
    const localeMap = { en: 'en-IN', ta: 'ta-IN', hi: 'hi-IN' };
    utt.lang = localeMap[lang] || 'en-IN';
    utt.onend = () => setSpeaking(false);
    utt.onerror = () => setSpeaking(false);
    utterRef.current = utt;
    setSpeaking(true);
    window.speechSynthesis.speak(utt);
  };

  const hasTTS = typeof window !== 'undefined' && !!window.speechSynthesis;

  return (
    <div className='d-flex align-items-center gap-2 flex-wrap mt-2' style={{ fontFamily: 'var(--font-mono)', fontSize: '0.75rem' }}>
      {/* Language selector */}
      <div className='d-flex gap-1'>
        {LANGUAGES.map(l => (
          <button
            key={l.code}
            onClick={() => handleLangChange(l.code)}
            disabled={translating}
            style={{
              padding: '3px 8px',
              borderRadius: '4px',
              fontSize: '0.72rem',
              width: 'auto',
              background: lang === l.code ? 'var(--theme-accent-glow, rgba(0,245,212,0.12))' : 'transparent',
              border: `1px solid ${lang === l.code ? 'var(--theme-accent, #00f5d4)' : 'rgba(255,255,255,0.15)'}`,
              color: lang === l.code ? 'var(--theme-accent, #00f5d4)' : 'rgba(255,255,255,0.5)',
              transition: 'all 0.2s',
            }}
          >{l.label}</button>
        ))}
      </div>
      {/* Listen button */}
      {hasTTS ? (
        <button
          onClick={handleListen}
          disabled={translating}
          style={{
            padding: '3px 10px',
            borderRadius: '4px',
            fontSize: '0.72rem',
            width: 'auto',
            background: speaking ? 'rgba(255,51,102,0.1)' : 'transparent',
            border: `1px solid ${speaking ? '#ff3366' : 'rgba(255,255,255,0.2)'}`,
            color: speaking ? '#ff3366' : 'rgba(255,255,255,0.6)',
          }}
        >
          {translating ? '...' : speaking ? '⏹ Stop' : `🔊 ${label}`}
        </button>
      ) : (
        <span style={{ color: 'rgba(255,255,255,0.3)', fontSize: '0.68rem' }}>TTS not supported</span>
      )}
    </div>
  );
}

export default VoiceExplainer;
```

